+
+#include "searchengine/searchengine.hpp"
+
+namespace {
+
+bool check(bool condition, std::string_view name) {
+    if (condition) {
+        std::cout << "[PASS] " << name << '\n';
+        return true;
+    }
+
+    std::cout << "[FAIL] " << name << '\n';
+    return false;
+}
+
+bool has_size(const Option<std::vector<Index>>& result, size_t expected) {
+    return result.has_value() && result->size() == expected;
+}
+
+std::filesystem::path write_book(
+    const std::filesystem::path& dir, std::string_view filename, std::string_view text) {
+    const std::filesystem::path path = dir / filename;
+    std::ofstream output{path};
+    output << text;
+    return path;
+}
+
+}  // namespace
+
+int main() {
+    const std::filesystem::path temp_dir = std::filesystem::temp_directory_path() / "hp_search_test";
+    std::filesystem::create_directories(temp_dir);
+
+    const std::filesystem::path book1_path = write_book(
+        temp_dir,
+        "book_one.txt",
+        "Harry Potter met Ron Weasley.\n"
+        "Magic magic wand.\n"
+        "\n"
+        "Hermione knows magic spells.\n");
+    const std::filesystem::path book2_path = write_book(
+        temp_dir,
+        "book_two.txt",
+        "Voldemort fears Harry.\n"
+        "Ron and Hermione help Harry.\n"
+        "\n"
+        "Magic is not ordinary.\n");
+
+    bool ok = true;
+
+    Result<Book> book1 = Book::create(book1_path.string());
+    Result<Book> book2 = Book::create(book2_path.string());
+    ok &= check(book1.has_value(), "Book::create reads first file");
+    ok &= check(book2.has_value(), "Book::create reads second file");
+
+    if (!book1.has_value() || !book2.has_value()) {
+        std::filesystem::remove_all(temp_dir);
+        return 1;
+    }
+
+    SearchEngine engine;
+    engine.add_book(std::move(*book1));
+    engine.add_book(std::move(*book2));
+
+    const Option<std::vector<std::string>> books = engine.get_books();
+    ok &= check(
+        books.has_value() && *books == std::vector<std::string>{"book_one.txt", "book_two.txt"},
+        "get_books returns inserted book names");
+
+    ok &= check(has_size(engine.search("harry"), 3), "search finds all normalized word matches");
+    ok &= check(has_size(engine.search_or("voldemort wand"), 2), "search_or combines matches");
+    ok &= check(has_size(engine.search_and("ron hermione"), 2), "search_and keeps books with every word");
+    ok &= check(has_size(engine.search_phrase("ron and hermione"), 3), "search_phrase finds adjacent words");
+    ok &= check(has_size(engine.search_not("harry voldemort"), 1), "search_not excludes books with later words");
+    ok &= check(has_size(engine.search_near("ron", "hermione", 2), 2), "search_near finds words within distance");
+    ok &= check(!engine.search("dumbledore").has_value(), "search returns nullopt for missing words");
+
+    const Option<std::vector<std::string>> top_words = engine.get_top_words(3);
+    ok &= check(
+        top_words.has_value() && *top_words == std::vector<std::string>{"harry", "magic", "hermione"},
+        "get_top_words sorts by count then word");
+
+    const Option<std::vector<Index>> harry = engine.search("harry");
+    if (harry.has_value() && !harry->empty()) {
+        const Context context = engine.get_context(harry->front());
+        ok &= check(context.prev.empty(), "get_context has no previous paragraph at file start");
+        ok &= check(
+            context.cur == "Harry Potter met Ron Weasley.\nMagic magic wand.",
+            "get_context returns current paragraph");
+        ok &= check(context.next == "Hermione knows magic spells.", "get_context returns next paragraph");
+    } else {
+        ok &= check(false, "get_context has a search result to inspect");
+    }
+
+    std::filesystem::remove_all(temp_dir);
+
+    if (ok) {
+        std::cout << "All SearchEngine tests passed.\n";
+        return 0;
+    }
+
+    std::cout << "Some SearchEngine tests failed.\n";
+    return 1;
+}
